SourceCode.Declaration:
/// <summary>
/// Central store ui builder class
/// </summary>
public final class NDXCSDUIBuilder extends SysOperationAutomaticUIBuilder
{
    NDXCSDContract csdContract;
    DialogField dlgfAll, dlgfCSDId, dlgValidFrom;

}

Method.Source:
public void build()
{
    super();
    csdContract = this.dataContractObject() as NDXCSDContract;
    dlgfAll = this.bindInfo().getDialogField(csdContract, methodStr(NDXCSDContract ,parmCSDAll));
    dlgfCSDId = this.bindInfo().getDialogField(csdContract, methodStr(NDXCSDContract ,parmCSId));
    dlgValidFrom = this.bindInfo().getDialogField(csdContract, methodStr(NDXCSDContract , parmValidFrom));
    dlgfAll.visible(csdContract.parmAllVisible());
    dlgfCSDId.enabled(false);

    dlgValidFrom.visible(false);
    if(csdContract.parmCommon() is NDX_CentralStoreDistributionTable)
    {
        dlgValidFrom.visible(true);
    }
    dlgValidFrom.enabled(false);
}
